data.xinshengCustomCss:
@import url('https://fonts.googleapis.com/css2?family=Courier+Prime:wght@700&display=swap');

.xt-root {
    --xt-bg: #000000;
    --xt-text: #b33030; 
    --xt-accent: #ff0000;
    --xt-font: 'Courier Prime', monospace;
    background: #000 !important;
    border: 1px solid #300;
    padding-top: 35px !important;
}

/* 右上角 REC 标 */
.xt-root::after {
    content: "● REC";
    position: absolute;
    top: 15px; right: 20px;
    color: #ff0000;
    font-size: 12px;
    font-weight: bold;
    animation: rec-blink 1s steps(2) infinite;
    z-index: 100;
}
@keyframes rec-blink { 0%, 100% { opacity: 1; } 50% { opacity: 0; } }

/* 方形头像 */
.xt-avatar {
    border-radius: 0 !important;
    border: 2px solid #ff0000;
    width: 75px; height: 75px;
    filter: none !important;
}

.xt-name { color: #ff0000; font-size: 22px; letter-spacing: 2px; }

/* 头像下方两个填充方块样式优化 */
.xt-row { margin: 10px 0 !important; }
.xt-card {
    background: #080000 !important;
    border: 1px solid #2d0a0a !important;
    padding: 10px !important;
    border-radius: 0 !important;
    min-height: 50px; /* 确保盒子有高度 */
}
.xt-card-title {
    font-size: 9px !important;
    color: #500 !important;
    text-transform: uppercase;
}
.xt-card .xt-text {
    color: #fff !important;
    font-size: 12px !important;
    font-weight: bold;
    text-align: center;
}

/* 核心：坐标与热感区块分行与显示 */
.xt-section-body {
    background: rgba(15, 0, 0, 0.9) !important;
    border-left: 2px solid #ff0000 !important;
    color: #cc7777 !important;
    font-size: 14px !important;
    line-height: 1.8;
    max-height: 160px;
    overflow-y: auto !important;
    padding: 12px !important;
}

/* 评论区：展开后独立滚动 */
.xt-collapse {
    border: 1px solid #300 !important;
    background: #000 !important;
    margin-top: 15px;
}
.xt-collapse-header {
    background: #1a0000 !important;
    color: #ff0000 !important;
}
#xt-t1:checked ~ .xt-content .xt-collapse-body {
    max-height: 300px !important;
    overflow-y: auto !important;
}

.xt-list-item {
    background: #030000 !important;
    border-bottom: 1px solid #1a0000 !important;
    color: #a64d4d !important;
    font-size: 13px;
    padding: 15px !important;
}

/* 评论网名加红 */
.xt-list-item::first-line {
    color: #ff3333;
    font-weight: bold;
}

/* 滚动条 */
::-webkit-scrollbar { width: 3px; }
::-webkit-scrollbar-thumb { background: #600; }
::-webkit-scrollbar-track { background: #000; }

.xt-section-title { color: #500 !important; font-size: 9px; }
.xt-footer { color: #1a1a1a; font-size: 8px; text-align: center; }

